from pathlib import Path
import json
q=Path(__file__).resolve().parent;rows=json.loads((q/'bank-rows-v2.json').read_text())
def add(question,a,ref,novel):rows.append({'id':f'Q{len(rows)+1:02}','question':question,'expected_answer':a,'source_references':ref,'novelty':novel})
add('When during Reveal do you total, announce and set Combat strength, can you update it during the turn, and how is strength over 20 marked?', 'After Reveal Cards and before Clean Up, at any point while resolving effects; announce total, set marker and update as needed. Above20 flip +20 side and count again from beginning of track.', 'Main pp12–13 / extraction 652–665,733–738','Flexible strength-setting timing and marker overflow')
add('When is a Leader’s Signet Ring ability activated, does merely revealing Signet Ring activate it, and can card text override normal game rules?', 'Activated when playing Signet Ring on an Agent turn, not when merely revealing. Left Leader ability used as described. Cards of any type can override normal rules.', 'Main p6,p20 / extraction 306–310,327–329,1162–1164','Generic Signet trigger and rules precedence')
add('How is a Recall Spy icon on a card resolved, where does the Spy go, and is it automatically the same as Infiltrate or Gather Intelligence?', 'Return one of own Spies from observation post to supply, usually a cost for card effect. Card recall distinct from the two voluntary recalls for Infiltrate or Gather Intelligence; it does not automatically give either benefit.', 'Main p11,p20 / extraction 603–605,1150–1151','Card recall destination versus voluntary recall purpose')
add('What does the “trash an Intrigue” icon allow you to choose, as opposed to an ordinary discard-a-card instruction?', 'Trash an Intrigue of choice from own hand. Ordinary discard chooses a non-Intrigue from hand unless explicitly specified.', 'Main p20 / extraction 1104–1106,1184','Dedicated Intrigue trash versus ordinary deck discard')
namespace={'__file__':str(q/'build_bank.py')};source=(q/'build_bank.py').read_text();exec(source[:source.index("write('benchmark-v1',rows)")],namespace);namespace['write']('benchmark-v3',rows)
(q/'bank-rows-v3.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n');print(len(rows))
